//! The native resolver against TS `resolveEngineRoutingPlan`, generated by
//! packages/safe-cex/src/transport/engine.native-routing-port.test.ts.
use safe_cex_native::RoutingPlan;
use safe_cex_native::resolve::{
    AccountTransport, Provider, RoutingInputs, account_transport, resolve_routing_plan,
};
use serde::Deserialize;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    exchange: String,
    #[serde(rename = "baseURL")]
    base_url: String,
    account: Option<AccountTransport>,
    provider: Provider,
    options: serde_json::Value,
    plan: Option<serde_json::Value>,
    error: Option<String>,
}

/// The fields the native host applies, so absent-vs-default never differs.
fn applied(plan: serde_json::Value) -> serde_json::Value {
    let plan: RoutingPlan = serde_json::from_value(plan).expect("TS plan decodes");
    serde_json::to_value(plan).unwrap()
}

#[test]
fn every_case_matches_the_typescript_resolver() {
    let cases: Vec<Case> =
        serde_json::from_str(include_str!("fixtures/routing-port-plans.json")).unwrap();
    assert!(cases.len() > 400);
    for case in cases {
        let label = format!("{} {:?} {}", case.exchange, case.provider, case.options);
        let inputs: RoutingInputs = serde_json::from_value(case.options.clone()).unwrap();
        if let Some(account) = &case.account {
            let derived = account_transport(&case.exchange, account).unwrap();
            assert_eq!(
                derived.tealstreet_proxy, inputs.tealstreet_proxy,
                "proxy {label}"
            );
            assert_eq!(
                derived.tealstreet_tunnel, inputs.tealstreet_tunnel,
                "tunnel {label}"
            );
            assert_eq!(derived.proxy_region, inputs.proxy_region, "region {label}");
            assert_eq!(
                derived.tealstreet_ws_route, inputs.tealstreet_ws_route,
                "wsRoute {label}"
            );
        }
        let result = resolve_routing_plan(&case.exchange, &inputs, &case.base_url, case.provider);
        match (result, case.plan, case.error) {
            (Ok(plan), Some(expected), None) => {
                assert_eq!(
                    serde_json::to_value(plan).unwrap(),
                    applied(expected),
                    "{label}"
                )
            }
            (Err(error), None, Some(expected)) => {
                assert_eq!(error.to_string(), expected, "{label}")
            }
            (result, plan, error) => panic!("{label}: {result:?} vs plan {plan:?} error {error:?}"),
        }
    }
}

/// Every route that attaches the account's proxy token targets a table host.
#[test]
fn authorized_routes_only_ever_name_table_hosts() {
    let table: serde_json::Value =
        serde_json::from_str(include_str!("../src/routing/table.json")).unwrap();
    let hosts = &table["hosts"];
    let mut allowed: Vec<&str> = hosts["privateProxy"]
        .as_object()
        .unwrap()
        .values()
        .map(|v| v.as_str().unwrap())
        .collect();
    allowed.push(hosts["publicCorsProxy"].as_str().unwrap());
    let cases: Vec<Case> =
        serde_json::from_str(include_str!("fixtures/routing-port-plans.json")).unwrap();
    let mut authorized = 0;
    for case in cases.iter().filter(|c| c.provider == Provider::Tealstreet) {
        let inputs: RoutingInputs = serde_json::from_value(case.options.clone()).unwrap();
        let Ok(plan) = resolve_routing_plan(&case.exchange, &inputs, &case.base_url, case.provider)
        else {
            continue;
        };
        for route in [
            Some(&plan.http),
            plan.public_http.as_ref(),
            plan.public_cors_http.as_ref(),
        ]
        .into_iter()
        .flatten()
        .filter(|route| route.authorize)
        {
            authorized += 1;
            assert!(
                allowed.contains(&route.prefix.as_str()),
                "{} {}",
                case.exchange,
                route.prefix
            );
        }
    }
    assert!(authorized > 50);
}

#[test]
fn an_override_proxy_url_input_refuses() {
    let smuggled = serde_json::json!({"tealstreetProxy": true, "hasKey": true, "overrideProxyUrl": "https://evil.invalid"});
    assert!(serde_json::from_value::<RoutingInputs>(smuggled).is_err());
}
